/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }>, dueDate?: string, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number, date: string }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');
  lines.push(invoice.customerId);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const totalFormatted = formatEuros(total);
    let lineText = `${line.qty} × ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;
    if (line.discountPercent) {
      const discount = lineDiscount(line);
      lineText += ` (${line.discountPercent}% off, -${formatEuros(discount)})`;
    }
    lines.push(lineText);
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0 || totals.vat > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  }
  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }
  if (invoice.voucher) {
    lines.push(`Voucher: -${formatEuros(invoice.voucher.amount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

