import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText shows DRAFT for invoice without number', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('DRAFT\n'));
});

test('renderInvoiceText shows invoice number when present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('INV-2026-0001\n'));
});

test('renderInvoiceText shows customer ID on second line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[1], 'C-001');
});

test('renderInvoiceText shows single line item with formatted amounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[2], '5 × Design work (hour) @ €85.00 = €425.00');
});

test('renderInvoiceText shows multiple line items', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[2], '5 × Design work (hour) @ €85.00 = €425.00');
  assert.equal(lines[3], '10 × Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText shows correct total', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('Total:')));
  assert.ok(text.includes('€'));
});

test('renderInvoiceText formats unit prices correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[2], '100 × Sticker sheet @ €0.50 = €50.00');
});

test('renderInvoiceText handles small amounts correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 1, unitPrice: 980, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[2], '1 × Icon set (24 icons) @ €9.80 = €9.80');
});

test('renderInvoiceText handles large amounts correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 2, unitPrice: 120000, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[2], '2 × Logo package @ €1,200.00 = €2,400.00');
});

test('renderInvoiceText output is readable as a table', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 2.5 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2026-0001');
  assert.equal(lines[1], 'C-003');
  assert.ok(lines[2].includes('Design work'));
  assert.ok(lines[3].includes('Sticker sheet'));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText shows discount on line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[2].includes('(10% off'));
  assert.ok(lines[2].includes('-€42.50)'));
});

test('renderInvoiceText shows subtotal and discount when present', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('Discount:')));
});

test('renderInvoiceText shows multiple discounted lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[2].includes('10% off'));
  assert.ok(lines[3].includes('20% off'));
});

test('renderInvoiceText mixed discounted and non-discounted lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'STICKER', name: 'Sticker sheet', qty: 100, unitPrice: 50, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[2].includes('(10% off'));
  assert.equal(lines[3], '100 × Sticker sheet @ €0.50 = €50.00');
});

test('renderInvoiceText shows VAT line', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
});

test('renderInvoiceText shows subtotal with VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
  assert.ok(lines.some((l) => l.startsWith('Total:')));
});

test('renderInvoiceText does not show VAT line for 0% VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(!lines.some((l) => l.startsWith('VAT:')));
});

test('renderInvoiceText shows VAT with discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('Subtotal:')));
  assert.ok(lines.some((l) => l.startsWith('Discount:')));
  assert.ok(lines.some((l) => l.startsWith('VAT:')));
});

test('renderInvoiceText VAT line is above Total', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const vatIndex = lines.findIndex((l) => l.startsWith('VAT:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(vatIndex > 0);
  assert.ok(totalIndex > vatIndex);
});

test('renderInvoiceText with mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

