test('renderInvoiceText voucher before total', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const voucherIndex = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  assert.ok(voucherIndex > 0);
  assert.ok(totalIndex > voucherIndex);
});

test('renderInvoiceText does not show voucher when not present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(!lines.some((l) => l.startsWith('Voucher:')));
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    dueDate: '2026-10-21',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l === 'Due: 2026-10-21'));
});

test('renderInvoiceText due date after total', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    dueDate: '2026-10-21',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIndex = lines.findIndex((l) => l.startsWith('Due:'));
  assert.ok(dueIndex > totalIndex);
});

test('renderInvoiceText does not show due date when not present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(!lines.some((l) => l.startsWith('Due:')));
});

test('renderInvoiceText shows paid amount when payments present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
    payments: [{ amount: 20000, date: '2026-10-10' }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some((l) => l.startsWith('Paid:')));
  assert.ok(text.includes('€200.00'));
});

test('renderInvoiceText paid after due', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    dueDate: '2026-10-21',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
    payments: [{ amount: 20000, date: '2026-10-10' }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const dueIndex = lines.findIndex((l) => l.startsWith('Due:'));
  const paidIndex = lines.findIndex((l) => l.startsWith('Paid:'));
  assert.ok(paidIndex > dueIndex);
});

test('renderInvoiceText aggregates multiple payments', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
